package com.masterlearning.platform.modules.course.entity;
import com.masterlearning.platform.common.entity.BaseEntity; import com.masterlearning.platform.modules.organization.entity.Organization; import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="courses") public class Course extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,length=180) private String title; @Column(unique=true,length=220) private String slug; @Column(length=2000) private String description; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private CourseStatus status=CourseStatus.DRAFT; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="organization_id") private Organization organization; protected Course(){} public Course(String t,String s,String d,Organization o){title=t;slug=s;description=d;organization=o;} public UUID getId(){return id;} public String getTitle(){return title;} public String getSlug(){return slug;} public String getDescription(){return description;} public CourseStatus getStatus(){return status;} public Organization getOrganization(){return organization;} public void publish(){status=CourseStatus.PUBLISHED;} public void archive(){status=CourseStatus.ARCHIVED;} }